}

def check_file_exists(filepath):
    """Check if a file exists and is not empty."""
    if not os.path.exists(filepath):
        return False, f"File not found: {filepath}"
    if os.path.getsize(filepath) == 0:
        return False, f"File is empty: {filepath}"
    return True, f"File exists and is not empty: {filepath}"

def check_csv_structure(filepath, expected_columns):
    """Check if a CSV file has the expected columns."""
    if not os.path.exists(filepath):
        return False, f"File not found: {filepath}"

    try:
        with open(filepath, 'r', newline='', encoding='utf-8') as f:
            reader = csv.reader(f)
            headers = next(reader, None)
            if headers is None:
                return False, f"CSV file has no header: {filepath}"

            # Check if expected columns exist
            missing = [col for col in expected_columns if col not in headers]
            if missing:
                return False, f"CSV missing expected columns: {filepath} - missing: {missing}"

            # Check if file has data rows
            rows = list(reader)
            if not rows:
                return False, f"CSV file has no data rows: {filepath}"

            return True, f"CSV has valid structure with {len(rows)} data rows: {filepath}"
    except Exception as e:
        return False, f"Error reading CSV {filepath}: {e}"

def check_numeric_columns(filepath, numeric_columns):
    """Check if specified columns contain numeric values."""
    try:
        with open(filepath, 'r', newline='', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            rows = list(reader)

            for row in rows:
                for col in numeric_columns:
                    if col not in row or row[col] == '':
                        return False, f"Column '{col}' in '{filepath}' has non-numeric values"
                    try:
                        float(row[col])
                    except ValueError:
                        return False, f"Column '{col}' in '{filepath}' has non-numeric values"

            return True, f"All numeric columns valid in {filepath}"
    except Exception as e:
        return False, f"Error checking numeric columns in {filepath}: {e}"

def check_column_count(filepath, expected_columns):
    """Check if all rows have the expected number of columns."""
    try:
        with open(filepath, 'r', newline='', encoding='utf-8') as f:
            reader = csv.reader(f)
            headers = next(reader, None)
            if headers is None:
                return False, f"CSV file has no header: {filepath}"

            expected_count = len(headers)
            row_count = 0
            for row in reader:
                row_count += 1
                if len(row) != expected_count:
                    return False, f"Row {row_count} in '{filepath}' has {len(row)} columns, expected {expected_count}"

            return True, f"All {row_count} rows have correct column count in {filepath}"
    except Exception as e:
        return False, f"Error checking column count in {filepath}: {e}"

