    """Run all validation checks and return results."""
    results = []

    # Check 1: File existence for all required files
    for filename, filepath in REQUIRED_FILES.items():
        passed, message = check_file_exists(filepath)
        results.append({
            "check_name": f"file_exists_{filename}",
            "passed": passed,
            "message": message
        })

    # Check 2: CSV structure for each file
