    }

    for filename, expected_columns in csv_files.items():
        filepath = REQUIRED_FILES[filename]
        passed, message = check_csv_structure(filepath, expected_columns)
        results.append({
            "check_name": f"csv_structure_{filename}",
            "passed": passed,
            "message": message
        })

    # Check 3: Numeric column validation
    numeric_columns = {
        't01_selected_indicators.csv': ['expected_direction'],  # Check if expected_direction is valid
        't05_clean_stops.csv': ['stop_lat', 'stop_lon'],
        't08_pois_clean.csv': ['latitude', 'longitude'],
        't10_accessibility_scores.csv': ['distance_m', 'n_departures', 'n_routes', 'accessibility_score'],
        't13_city_clusters.csv': ['year', 'cluster_id'],
    }

    for filename, numeric_cols in numeric_columns.items():
        filepath = REQUIRED_FILES[filename]
        passed, message = check_numeric_columns(filepath, numeric_cols)
        results.append({
            "check_name": f"numeric_columns_{filename}",
            "passed": passed,
            "message": message
        })

    # Check 4: Column count validation
    for filename, expected_columns in csv_files.items():
        filepath = REQUIRED_FILES[filename]
        passed, message = check_column_count(filepath, expected_columns)
        results.append({
            "check_name": f"column_count_{filename}",
            "passed": passed,
            "message": message
        })

    return results

def main():
    results = run_validation()

    # Write results to JSON file
    output_path = 'outputs/t14_validation_summary.json'
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=2)

